// ============================================================================
// Spec item 1: selector table matches `cast sig` for every function
// `routers.selectors.*` claims to compute.
// ============================================================================

test "spec item 1: selector table matches cast sig literals" {
    try testing.expectEqualSlices(u8, &sel("cac88ea9"), &r.selectors.aerodrome_swap_exact_tokens_for_tokens);
    try testing.expectEqualSlices(u8, &sel("903638a4"), &r.selectors.aerodrome_swap_exact_eth_for_tokens);
    try testing.expectEqualSlices(u8, &sel("c6b7f1b6"), &r.selectors.aerodrome_swap_exact_tokens_for_eth);
    try testing.expectEqualSlices(u8, &sel("4111d597"), &r.selectors.aerodrome_unsafe_swap_exact_tokens_for_tokens);
    try testing.expectEqualSlices(u8, &sel("88cd821e"), &r.selectors.aerodrome_swap_exact_tokens_for_tokens_fot);
    try testing.expectEqualSlices(u8, &sel("3da5acba"), &r.selectors.aerodrome_swap_exact_eth_for_tokens_fot);
    try testing.expectEqualSlices(u8, &sel("12bc3aca"), &r.selectors.aerodrome_swap_exact_tokens_for_eth_fot);

    try testing.expectEqualSlices(u8, &sel("a026383e"), &r.selectors.slipstream_exact_input_single);
    try testing.expectEqualSlices(u8, &sel("c714e838"), &r.selectors.slipstream_exact_output_single);

    try testing.expectEqualSlices(u8, &sel("ac3893ba"), &r.selectors.camelot_v2_swap_exact_tokens_for_tokens_fot);
    try testing.expectEqualSlices(u8, &sel("b4822be3"), &r.selectors.camelot_v2_swap_exact_eth_for_tokens_fot);
    try testing.expectEqualSlices(u8, &sel("52aa4c22"), &r.selectors.camelot_v2_swap_exact_tokens_for_eth_fot);

    try testing.expectEqualSlices(u8, &sel("bc651188"), &r.selectors.camelot_v3_exact_input_single);
    try testing.expectEqualSlices(u8, &sel("b87d2524"), &r.selectors.camelot_v3_exact_input_single_fot);

    try testing.expectEqualSlices(u8, &sel("b4554231"), &r.selectors.pancake_exact_input_stable_swap);
    try testing.expectEqualSlices(u8, &sel("b4c4e555"), &r.selectors.pancake_exact_output_stable_swap);

    // Selectors Phase 2 routers share with existing Uniswap decoders
    // (collision surface for C1): exactInput/exactOutput (path-based) are
    // reused byte-for-byte by Slipstream and Camelot V3.
    try testing.expectEqualSlices(u8, &sel("c04b8d59"), &c.selectors.exact_input);
    try testing.expectEqualSlices(u8, &sel("f28c0498"), &c.selectors.exact_output);
}

// ============================================================================
// Spec item 2: real fixtures decode with the right router-specific semantics.
// Aerodrome Router (Base) / Velodrome V2 Router (Optimism), via .aerodrome.
// ============================================================================

test "fixture: base_aerodrome_0xcac88ea9 swapExactTokensForTokens via .aerodrome" {
    const decoded = r.decodeFor(.aerodrome, &F_AERO_CAC88EA9);
    try testing.expect(decoded != null);
    const s = switch (decoded.?) {
        .aerodrome_swap_exact_tokens_for_tokens => |v| v,
        else => return error.WrongVariant,
    };
    try testing.expectEqual(@as(u256, 2914639692791), s.amount_in);
    try testing.expectEqual(@as(u256, 196018080), s.amount_out_min);
    try testing.expectEqual(@as(usize, 2), s.routes.len());
    const hop0 = s.routes.get(0);
    try testing.expectEqualSlices(u8, &addr("ecff4d80f54cf55c626e52f304a8891645961e72"), &hop0.from);
    try testing.expectEqualSlices(u8, &addr("4200000000000000000000000000000000000006"), &hop0.to);
    try testing.expectEqual(false, hop0.stable);
    try testing.expectEqualSlices(u8, &addr("420dd381b31aef6683db6b902084cb0ffece40da"), &hop0.factory);
    const hop1 = s.routes.get(1);
    try testing.expectEqualSlices(u8, &addr("4200000000000000000000000000000000000006"), &hop1.from);
    try testing.expectEqualSlices(u8, &addr("833589fcd6edb6e08f4c7c32d4f71b54bda02913"), &hop1.to);
    try testing.expectEqualSlices(u8, &addr("c4affdf828cd2e70d7695733eb24be80411791f7"), &s.to);
    try testing.expectEqual(@as(u256, 1790220262), s.deadline);
}

