// ============================================================================

test "fixture: bsc_pancake_ur_0x3593564c_22080604 stable swap + v2 swap + pay_portion + sweep via .pancake_ur" {
    const decoded = r.decodeFor(.pancake_ur, &F_PUR_22080604);
    try testing.expect(decoded != null);
    const ur = switch (decoded.?) {
        .universal_router_execute => |v| v,
        else => return error.WrongVariant,
    };
    try testing.expectEqual(@as(?u256, 1790222564), ur.deadline);
    try testing.expectEqualSlices(u8, &[_]u8{ 0x22, 0x08, 0x06, 0x04 }, ur.commands);

    var it = ur.iterator();

    const cmd0 = it.next().?;
    const stable_in = switch (cmd0.payload) {
        .stable_swap_exact_in => |p| p,
        else => return error.WrongVariant,
    };
    try testing.expectEqualSlices(u8, &addr("ea26b78255df2bbc31c1ebf60010d78670185bd0"), &stable_in.recipient);
    try testing.expectEqual(@as(u256, 51000000000000000000), stable_in.amount0);
    try testing.expectEqual(@as(u256, 0), stable_in.amount1);
    try testing.expectEqual(@as(usize, 2), stable_in.path.len());
    try testing.expectEqualSlices(u8, &addr("55d398326f99059ff775485246999027b3197955"), &stable_in.path.get(0));
    try testing.expectEqualSlices(u8, &addr("8ac76a51cc950d9822d68b83fe1ad97b32cd580d"), &stable_in.path.get(1));
    try testing.expectEqual(@as(usize, 1), stable_in.flags.len());
    try testing.expectEqual(@as(u256, 2), stable_in.flags.get(0));
    try testing.expectEqual(true, stable_in.payer_is_user);

    const cmd1 = it.next().?;
    const v2in = switch (cmd1.payload) {
        .v2_swap_exact_in => |p| p,
        else => return error.WrongVariant,
    };
    // Recipient sentinel 0x0...02 == ADDRESS_THIS (Dispatcher.map); decode
    // does not resolve it, so the raw sentinel bytes are what's stored.
    try testing.expectEqualSlices(u8, &addr("0000000000000000000000000000000000000002"), &v2in.recipient);
    try testing.expectEqual(@as(u256, 1) << 255, v2in.amount_in); // CONTRACT_BALANCE sentinel
    try testing.expectEqual(@as(u256, 18871814985802432), v2in.amount_out_min);
    try testing.expectEqualSlices(u8, &addr("8ac76a51cc950d9822d68b83fe1ad97b32cd580d"), &v2in.path.first());
    try testing.expectEqualSlices(u8, &addr("2170ed0880ac9a755fd29b2688956bd959f933f8"), &v2in.path.last());
    try testing.expectEqual(false, v2in.payer_is_user);

    const cmd2 = it.next().?;
    const pay_portion = switch (cmd2.payload) {
        .pay_portion => |p| p,
        else => return error.WrongVariant,
    };
    try testing.expectEqualSlices(u8, &addr("2170ed0880ac9a755fd29b2688956bd959f933f8"), &pay_portion.token);
    try testing.expectEqualSlices(u8, &addr("6a80f57ac54123cb71e6c79b3935a381b87b4308"), &pay_portion.recipient);
    try testing.expectEqual(@as(u256, 25), pay_portion.amount);

    const cmd3 = it.next().?;
    const sweep = switch (cmd3.payload) {
        .sweep => |p| p,
        else => return error.WrongVariant,
    };
    try testing.expectEqualSlices(u8, &addr("2170ed0880ac9a755fd29b2688956bd959f933f8"), &sweep.token);
    try testing.expectEqualSlices(u8, &addr("26a50b11214838d5b46060e6ddd851baee4ced81"), &sweep.recipient);
    try testing.expectEqual(@as(u256, 18824164832451717), sweep.amount);

    try testing.expect(it.next() == null);
}

