test "round trip: aerodrome swapExactTokensForTokens (2-hop, mixed stable flags)" {
    const allocator = testing.allocator;
    var route1 = routeTuple(RT_TOKEN_A, RT_TOKEN_B, false, RT_FACTORY);
    var route2 = routeTuple(RT_TOKEN_B, RT_TOKEN_C, true, RT_FACTORY);
    const routes = [_]AV{ .{ .tuple = &route1 }, .{ .tuple = &route2 } };
    const values = [_]AV{
        .{ .uint256 = 1000 }, .{ .uint256 = 900 }, .{ .array = &routes }, .{ .address = RT_TO }, .{ .uint256 = 1234567890 },
    };
    const encoded = try abi_encode.encodeFunctionCall(allocator, r.selectors.aerodrome_swap_exact_tokens_for_tokens, &values);
    defer allocator.free(encoded);
    const decoded = r.decodeFor(.aerodrome, encoded);
    try testing.expect(decoded != null);
    const s = switch (decoded.?) {
        .aerodrome_swap_exact_tokens_for_tokens => |v| v,
        else => return error.WrongVariant,
    };
    try testing.expectEqual(@as(u256, 1000), s.amount_in);
    try testing.expectEqual(@as(u256, 900), s.amount_out_min);
    try testing.expectEqual(@as(usize, 2), s.routes.len());
    const hop0 = s.routes.get(0);
    try testing.expectEqualSlices(u8, &RT_TOKEN_A, &hop0.from);
    try testing.expectEqualSlices(u8, &RT_TOKEN_B, &hop0.to);
    try testing.expectEqual(false, hop0.stable);
    try testing.expectEqualSlices(u8, &RT_FACTORY, &hop0.factory);
    try testing.expectEqual(true, s.routes.get(1).stable);
    try testing.expectEqualSlices(u8, &RT_TO, &s.to);
    try testing.expectEqual(@as(u256, 1234567890), s.deadline);
}

