    const encoded = try abi_encode.encodeFunctionCall(allocator, r.selectors.camelot_v3_exact_input_single, &values);
    defer allocator.free(encoded);
    const decoded = r.decodeFor(.camelot_v3, encoded);
    try testing.expect(decoded != null);
    const s = switch (decoded.?) {
        .camelot_v3_exact_input_single => |v| v,
        else => return error.WrongVariant,
    };
    try testing.expectEqualSlices(u8, &RT_TOKEN_A, &s.token_in);
    try testing.expectEqual(@as(u256, 1000), s.amount_in);
    try testing.expectEqual(@as(u256, 999), s.deadline);
}

