test "reject: aerodrome Route.stable bool = 2" {
    const allocator = testing.allocator;
    var b = Builder.init(allocator);
    defer b.deinit();
    try b.sel4(r.selectors.aerodrome_swap_exact_tokens_for_tokens);
    try b.w(1000);
    try b.w(900);
    try b.w(0xa0); // routes offset: right after the 5-word head
    try b.wAddr(RT_TO);
    try b.w(123);
    try b.w(1); // routes.length = 1
    try b.wAddr(RT_TOKEN_A);
    try b.wAddr(RT_TOKEN_B);
    try b.w(2); // stable: invalid, must be 0 or 1
    try b.wAddr(RT_FACTORY);
    const data = try b.ownedSlice();
    defer allocator.free(data);
    try testing.expectEqual(@as(?c.Decoded, null), r.decodeFor(.aerodrome, data));
}

test "reject: aerodrome Route[] length 0" {
    const allocator = testing.allocator;
    var b = Builder.init(allocator);
    defer b.deinit();
    try b.sel4(r.selectors.aerodrome_swap_exact_tokens_for_tokens);
    try b.w(1000);
    try b.w(900);
    try b.w(0xa0);
    try b.wAddr(RT_TO);
    try b.w(123);
    try b.w(0); // routes.length = 0: a swap always has at least one hop
    const data = try b.ownedSlice();
    defer allocator.free(data);
    try testing.expectEqual(@as(?c.Decoded, null), r.decodeFor(.aerodrome, data));
}

fn buildCamelotExactInputWithPathLen(allocator: std.mem.Allocator, path_len: usize) ![]u8 {
    const path = try allocator.alloc(u8, path_len);
    defer allocator.free(path);
    @memset(path, 0xAB);
    var tuple = [_]AV{
        .{ .bytes = path }, .{ .address = RT_RECIPIENT }, .{ .uint256 = 1 }, .{ .uint256 = 2 }, .{ .uint256 = 3 },
    };
    const values = [_]AV{.{ .tuple = &tuple }};
    return abi_encode.encodeFunctionCall(allocator, c.selectors.exact_input, &values);
}

test "reject: camelot_v3 AlgebraPath bad lengths (20, 50, 0 bytes)" {
    const allocator = testing.allocator;
    // Valid lengths are 20*n with n >= 2 (40, 60, ...); none of these fit.
    const bad_lengths = [_]usize{ 20, 50, 0 };
    for (bad_lengths) |len| {
        const encoded = try buildCamelotExactInputWithPathLen(allocator, len);
        defer allocator.free(encoded);
        try testing.expectEqual(@as(?c.Decoded, null), r.decodeFor(.camelot_v3, encoded));
    }
}

test "reject: slipstream tick_spacing with bad sign extension" {
    const allocator = testing.allocator;
    var b = Builder.init(allocator);
    defer b.deinit();
    try b.sel4(r.selectors.slipstream_exact_input_single);
    try b.wAddr(RT_TOKEN_A);
    try b.wAddr(RT_TOKEN_B);
    // tick_spacing word: low 3 bytes hold a valid negative int24 (-1), but a
    // byte higher up in the padding region is not the negative-fill 0xFF a
    // real ABI-encoded int24 always has.
    try b.wRaw(blk: {
        var word: [32]u8 = @splat(0xFF);
        word[5] = 0x00; // breaks the sign-extension fill
        word[29] = 0xFF;
        word[30] = 0xFF;
        word[31] = 0xFF;
        break :blk word;
    });
    try b.wAddr(RT_RECIPIENT);
    try b.w(999);
    try b.w(1000);
    try b.w(900);
    try b.w(0);
    const data = try b.ownedSlice();
    defer allocator.free(data);
    try testing.expectEqual(@as(?c.Decoded, null), r.decodeFor(.slipstream, data));
}

test "reject: camelot_v2 referrer with dirty padding" {
    const allocator = testing.allocator;
    var b = Builder.init(allocator);
    defer b.deinit();
    try b.sel4(r.selectors.camelot_v2_swap_exact_tokens_for_tokens_fot);
    try b.w(100); // amountIn
    try b.w(90); // amountOutMin
    try b.w(0xc0); // path offset: right after the 6-word head
    try b.wAddr(RT_TO);
    // referrer word: real address in the low 20 bytes, dirty byte in the
    // padding region a real ABI encoder always zeros.
    var dirty: [32]u8 = @splat(0);
    dirty[3] = 0x01;
    @memcpy(dirty[12..32], &RT_REFERRER);
    try b.wRaw(dirty);
    try b.w(55); // deadline
    try b.w(2); // path length
    try b.wAddr(RT_TOKEN_A);
    try b.wAddr(RT_TOKEN_B);
    const data = try b.ownedSlice();
    defer allocator.free(data);
    try testing.expectEqual(@as(?c.Decoded, null), r.decodeFor(.camelot_v2, data));
}

// ============================================================================
// Spec item 7 (B5): hostile input. Every accessor Phase 2's `decodeFor` can
// return is walked when non-null, so a real implementation's bugs (not just
// this test's own shape) are what a panic here would catch.
// ============================================================================

fn walkAddressPath(p: c.AddressPath) void {
    const n = p.len();
    var i: usize = 0;
    while (i < n) : (i += 1) _ = p.get(i);
    _ = p.first();
    _ = p.last();
}

fn walkV3Path(p: c.V3Path) void {
    const n = p.hops();
    var i: usize = 0;
    while (i < n) : (i += 1) {
        const h = p.hop(i);
        _ = h.tickSpacing();
    }
    _ = p.first();
    _ = p.last();
}

fn walkU256Array(a: c.U256Array) void {
    const n = a.len();
    var i: usize = 0;
    while (i < n) : (i += 1) _ = a.get(i);
}

fn walkAlgebraPath(p: c.AlgebraPath) void {
    const n = p.len();
    var i: usize = 0;
    while (i < n) : (i += 1) _ = p.get(i);
    _ = p.first();
    _ = p.last();
}

fn walkRouteArray(a: r.RouteArray) void {
    const n = a.len();
    var i: usize = 0;
    while (i < n) : (i += 1) _ = a.get(i);
}

fn walkUrCommand(cmd: c.Command) void {
    switch (cmd.payload) {
        .v3_swap_exact_in => |p| {
            walkV3Path(p.path);
            if (p.min_hop_price_x36) |a| walkU256Array(a);
        },
        .v3_swap_exact_out => |p| {
            walkV3Path(p.path);
            if (p.min_hop_price_x36) |a| walkU256Array(a);
        },
        .v2_swap_exact_in => |p| {
            walkAddressPath(p.path);
            if (p.min_hop_price_x36) |a| walkU256Array(a);
        },
        .v2_swap_exact_out => |p| {
            walkAddressPath(p.path);
            if (p.min_hop_price_x36) |a| walkU256Array(a);
        },
        .stable_swap_exact_in, .stable_swap_exact_out => |s| {
            walkAddressPath(s.path);
            walkU256Array(s.flags);
        },
        .execute_sub_plan => |sp| walkUrExecute(sp),
        else => {},
    }
}

fn walkUrExecute(ur: c.UniversalRouterExecute) void {
    var it = ur.iterator();
    while (it.next()) |cmd| walkUrCommand(cmd);
}

fn walkMulticall(m: c.Multicall) void {
    _ = m.len();
    var it = m.iterator();
    while (it.next()) |call| {
        switch (call) {
            .swap => |inner| walkDecoded(inner),
            .payment, .other => {},
        }
    }
}

fn walkDecoded(d: c.Decoded) void {
    switch (d) {
        .v2_swap_exact_tokens_for_tokens,
        .v2_swap_exact_tokens_for_eth,
        .v2_swap_exact_tokens_for_tokens_fot,
        .v2_swap_exact_tokens_for_eth_fot,
        .swap_router02_swap_exact_tokens_for_tokens,
        => |s| walkAddressPath(s.path),
        .v2_swap_tokens_for_exact_tokens,
        .v2_swap_tokens_for_exact_eth,
        .swap_router02_swap_tokens_for_exact_tokens,
        => |s| walkAddressPath(s.path),
        .v2_swap_exact_eth_for_tokens, .v2_swap_exact_eth_for_tokens_fot => |s| walkAddressPath(s.path),
        .v2_swap_eth_for_exact_tokens => |s| walkAddressPath(s.path),
        .v3_exact_input, .slipstream_exact_input => |s| walkV3Path(s.path),
        .v3_exact_output, .slipstream_exact_output => |s| walkV3Path(s.path),
        .v3_exact_input_single, .v3_exact_output_single => {},
        .slipstream_exact_input_single, .slipstream_exact_output_single => {},
        .camelot_v3_exact_input_single, .camelot_v3_exact_input_single_fot => {},
        .multicall => |m| walkMulticall(m),
        .universal_router_execute => |ur| walkUrExecute(ur),
        .aerodrome_swap_exact_tokens_for_tokens,
        .aerodrome_swap_exact_tokens_for_eth,
        .aerodrome_swap_exact_tokens_for_tokens_fot,
        .aerodrome_swap_exact_tokens_for_eth_fot,
        => |s| walkRouteArray(s.routes),
        .aerodrome_swap_exact_eth_for_tokens, .aerodrome_swap_exact_eth_for_tokens_fot => |s| walkRouteArray(s.routes),
        .aerodrome_unsafe_swap_exact_tokens_for_tokens => |s| {
            walkU256Array(s.amounts);
            walkRouteArray(s.routes);
        },
        .camelot_v2_swap_exact_tokens_for_tokens_fot, .camelot_v2_swap_exact_tokens_for_eth_fot => |s| walkAddressPath(s.path),
        .camelot_v2_swap_exact_eth_for_tokens_fot => |s| walkAddressPath(s.path),
        .camelot_v3_exact_input => |s| walkAlgebraPath(s.path),
        .camelot_v3_exact_output => |s| walkAlgebraPath(s.path),
        .pancake_exact_input_stable_swap => |s| {
            walkAddressPath(s.path);
            walkU256Array(s.flags);
        },
        .pancake_exact_output_stable_swap => |s| {
            walkAddressPath(s.path);
            walkU256Array(s.flags);
        },
    }
}

test "B5: hostile input - every prefix of every embedded Phase 2 fixture, through decodeFor with its router" {
    for (all_router_fixtures) |rf| {
        var len: usize = 0;
        while (len <= rf.data.len) : (len += 1) {
            if (r.decodeFor(rf.router, rf.data[0..len])) |d| walkDecoded(d);
        }
    }
}

test "B5: hostile input - 1,000 single-byte mutations per Phase 2 fixture, fixed seed, through decodeFor with its router" {
    const allocator = testing.allocator;
    var prng = std.Random.DefaultPrng.init(0xC0FFEE_D00D_1234);
    const rnd = prng.random();

    for (all_router_fixtures) |rf| {
        if (rf.data.len == 0) continue;
        const mutated = try allocator.alloc(u8, rf.data.len);
        defer allocator.free(mutated);

        var i: usize = 0;
        while (i < 1000) : (i += 1) {
            @memcpy(mutated, rf.data);
            const idx = rnd.uintLessThan(usize, rf.data.len);
            mutated[idx] = rnd.int(u8);
            if (r.decodeFor(rf.router, mutated)) |d| walkDecoded(d);
        }
    }
}
